interface Logger {
  prefix: string;
  log(this: Logger, message: string): void;
}

const logger: Logger = {
  prefix: '[APP]',
  log(message) {
    console.log(this.prefix, message);
  },
};

const broken = logger.log;
// broken('hi'); // Error: this may be undefined

class Counter {
  count = 0;

  incrementMethod() {
    this.count++;
  }

  incrementArrow = () => {
    this.count++;
  };
}

const c = new Counter();
const m = c.incrementMethod;
const a = c.incrementArrow;
// m(); // runtime: this undefined
a(); // works — lexical this

class Button {
  label = 'Click';

  handleClick() {
    console.log(this.label);
  }

  mount(el: HTMLElement) {
    el.addEventListener('click', this.handleClick.bind(this));
  }
}

type ClickHandler = (this: void, ev: MouseEvent) => void;

function register(handler: ClickHandler) {
  document.addEventListener('click', handler);
}

register(function (ev) {
  console.log(ev.clientX);
});
